import math

def is_prime(n):
    if n < 2: return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0: return False
    return True

primes = [i for i in range(data['limit']) if is_prime(i)]
count = len(primes)

result = {
    "holds": count == data['claimed'],
    "values": {
        "limit": data['limit'],
        "claimed": data['claimed'],
        "primes_found": primes,
        "count": count
    },
    "explanation": f"There are {count} prime numbers below {data['limit']}, which matches the claim if the count is {data['claimed']}."
}

print(result)

